struct Point { i32 x; i32 y; }
impl Point { fn i32 total(self){return self.x+self.y;} }
fn main(){Point p={x:7,y:11};println("{p.total()}");return 0;}

struct Point {i32 x;}
impl Point {@unsafe fn void change(self*,i32 x){self.x=x;} }
fn main(){Point p={x:7};unsafe {p.change(11);}println("{p.x}");return 0;}

struct Point {i32 x;}
impl Point {fn void change(self*,i32 x){self.x=x;} }
fn main(){Point p={x:7};p.change(11);println("{p.x}");return 0;}

struct Item {i32 value;}
impl Item {const SEED=7; fn Item create(i32 value){return Item{value:value};} }
fn main(){Item x=Item.create(Item.SEED);println("{x.value}");return 0;}

struct Box(T) {T value;}
impl Box(T) {fn T get(self){return self.value;} }
fn main(){Box(i32) a={value:7};Box(i64) b={value:(i64)11};println("{a.get()} {b.get()}");return 0;}

struct Pair(A,B) {A first;B second;}
impl(A,B) Pair(A,B) {fn A first_value(self){return self.first;} fn B second_value(self){return self.second;} }
fn main(){Pair(i32,i64) p={first:7,second:(i64)11};println("{p.first_value()} {p.second_value()}");return 0;}

struct Box(T){T value;}
impl Box(T){fn T get(self){return self.value;} }
fn main(){Box(i32) inner={value:7};Box(Box(i32)) outer={value:inner};let restored=outer.get();println("{restored.get()}");return 0;}

struct Outer{Inner inner;}
struct Inner{i32 value;}
fn main(){Outer x={inner:Inner{value:7}};println("{x.inner.value}");return 0;}

struct Item{i32 value;}
fn main(){Item x={value:7};println("{x.get()}");return 0;}
impl Item{fn i32 get(self){return self.value;} }

struct Item{i32 value;}
impl Item{fn i32 get(self){return 1;} fn i32 get(self){return 2;} }
fn main(){return 0;}

struct Item{i32 value;}
impl Item{const SEED=7;const SEED=11;}
fn main(){return 0;}

struct Item{i32 value;}
impl Item{fn i32 choose(self,i32 x){return self.value+x+10;} fn i32 choose(self,f64 x){return self.value+(i32)x+21;} }
fn main(){Item x={value:0};println("{x.choose(1)} {x.choose(1.5)}");return 0;}

struct Inner{i32 value;}
impl Inner{fn i32 get(self){return self.value;} }
struct Outer{Inner;}
fn main(){Outer x={Inner:Inner{value:7}};println("{x.value} {x.get()}");return 0;}

struct A{i32 value;} struct B{i32 value;}
impl A{fn i32 get(self){return 7;} } impl B{fn i32 get(self){return 11;} } struct C{A;B;}
fn main(){C x={};println("{x.get()}");return 0;}

struct A{i32 value;} impl A{fn i32 get(self){return self.value;} }
struct Deep{A;} struct B{i32 value;} impl B{fn i32 get(self){return self.value;} }
struct Outer{Deep;B;}
fn main(){Outer x={Deep:Deep{A:A{value:7}},B:B{value:11}};println("{x.get()}");return 0;}

