struct Item{i32 value;}
impl Item{@unsafe fn void set(self*,i32 v){self.value=v;} }
fn main(){const Item x={value:7};unsafe{x.set(11);}return 0;}

struct Point{i32 value;}
impl Point{fn void change(ref<Point> self,i32 value){self[0].value=value;} }
fn main(){owner<Point> points=own(1);ref<Point> view=ref_of(points);Point.change(view,11);println("{points[0].value}");return 0;}

